const $ = (selector, parent = document) => parent.querySelector(selector);
const $$ = (selector, parent = document) => [...parent.querySelectorAll(selector)];
const actions = ['goto', 'click', 'clickAndWaitForResponse', 'dblclick', 'hover', 'focus', 'fill', 'clear', 'type', 'check', 'uncheck', 'selectOption', 'press', 'waitForVisible', 'waitForHidden', 'waitForURL', 'waitForLoadState', 'waitForTimeout', 'reload', 'back', 'forward'];
const assertions = ['toBeVisible', 'toBeHidden', 'toBeEnabled', 'toBeDisabled', 'toBeChecked', 'toHaveText', 'toContainText', 'toHaveValue', 'toHaveCount', 'toHaveURL', 'toHaveTitle'];
const strategies = ['role', 'label', 'text', 'testId', 'placeholder', 'altText', 'title', 'css', 'xpath'];
const readinessTypes = ['none', 'elementAuto', 'elementVisible', 'elementHidden', 'elementEnabled', 'elementEditable', 'elementText', 'url', 'loadState'];
let state = { plans: [], suites: [], cases: [], flows: [], runs: [] };
let view = 'dashboard'; let selectedPlanId; let selectedSuiteId; let selectedCaseId; let selectedFlowId; let caseTab = 'visual'; let casePhase = 'steps'; let suitePhase = 'setupSteps'; let codeLanguage = 'javascript';

function esc(value = '') { return String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char])); }
function formatTime(value) { return value ? new Date(value).toLocaleString(window.I18N.intlLocale(), { hour12: false }) : '—'; }
function formatDuration(ms = 0) { return ms < 1000 ? `${ms} ms` : window.I18N.t(`${(ms / 1000).toFixed(1)} 秒`); }
function toast(message, type = '') { const node = document.createElement('div'); node.className = `toast ${type}`; node.textContent = window.I18N.t(message); $('#toastRegion').append(node); setTimeout(() => node.remove(), 4500); }
async function api(path, options = {}) {
  const response = await fetch(path, { headers: { 'Content-Type': 'application/json' }, ...options }); const body = response.status === 204 ? null : await response.json();
  if (!response.ok) { const error = new Error(window.I18N.translateError(body?.code, body?.error || '操作失败')); error.status = response.status; error.code = body?.code; error.payload = body; throw error; } return body;
}
async function refresh(keepContent = false) { state = await api('/api/state'); updateShell(); if (!keepContent) render(); }
function updateShell() { $('#planCount').textContent = state.plans.length; $('#suiteCount').textContent = state.suites.length; $('#caseCount').textContent = state.cases.length; $('#flowCount').textContent = state.flows.length; $('#runCount').textContent = state.runs.length; const completed = state.runs.filter(x => ['passed', 'failed'].includes(x.status)); const pass = completed.filter(x => x.status === 'passed').length; $('#navHealth').textContent = completed.length ? `${Math.round(pass / completed.length * 100)}%` : '—'; $$('.nav-link').forEach(x => x.classList.toggle('active', x.dataset.view === view)); }
function go(next, id) { view = next; selectedPlanId = next==='plans'?id:undefined; selectedSuiteId = next==='suites'?id:undefined; selectedCaseId = next==='cases'?id:undefined; selectedFlowId = next==='flows'?id:undefined; updateShell(); render(); }
function pageHeading(title, breadcrumb = 'coupayWeb testing') { $('#pageTitle').textContent = title; $('#breadcrumb').textContent = breadcrumb; }
function statusBadge(status) { const labels = { passed: '通过', failed: '失败', running: '执行中' }; return `<span class="status ${esc(status)}">${labels[status] || esc(status || '未知')}</span>`; }

function render() {
  if (view === 'dashboard') return renderDashboard();
  if (view === 'plans') return selectedPlanId ? renderPlanDetail() : renderPlans();
  if (view === 'suites') return selectedSuiteId ? renderSuiteDetail() : renderSuites();
  if (view === 'cases') return selectedCaseId ? renderCaseEditor() : renderCases();
  if (view === 'flows') return selectedFlowId ? renderFlowDetail() : renderFlows();
  if (view === 'runs') return renderRuns();
}
function renderDashboard() {
  pageHeading('概览'); const completed = state.runs.filter(x => ['passed', 'failed'].includes(x.status)); const passed = completed.filter(x => x.status === 'passed').length; const passRate = completed.length ? Math.round(passed / completed.length * 100) : 0; const latestFailed = state.runs.find(x => x.status === 'failed');
  $('#content').innerHTML = `<div class="hero"><div><h2>今天的测试状态</h2><p>从计划、用例到失败证据，都保存在这台电脑上。</p></div><button class="btn primary" id="dashNewPlan">${state.plans.length ? '新建测试计划' : '创建第一个测试计划'}</button></div>
    <div class="metrics"><div class="metric"><span>测试计划</span><strong>${state.plans.length}</strong><em>按顺序组织测试套件</em></div><div class="metric"><span>测试套件</span><strong>${state.suites.length}</strong><em>支持 Setup 和 Teardown</em></div><div class="metric"><span>测试用例</span><strong>${state.cases.length}</strong><em>${state.cases.filter(c=>c.editorMode==='code').length} 个代码用例</em></div><div class="metric"><span>公共流程</span><strong>${state.flows.length}</strong><em>可复用的场景步骤</em></div><div class="metric"><span>执行记录</span><strong>${state.runs.length}</strong><em>完整保留，可查询和删除</em></div><div class="metric"><span>通过率</span><strong>${passRate}%</strong><em>${passed} 通过 / ${completed.length} 已完成</em></div></div>
    <div class="grid-2"><div class="panel"><div class="panel-head"><div><h2>最近执行</h2><p>点击记录查看失败步骤和证据。</p></div><button class="btn small secondary" id="allRuns">查看全部</button></div><div class="list">${state.runs.slice(0,5).map(runRowHtml).join('') || emptyHtml('还没有执行记录','回放一个用例后，这里会显示结果。')}</div></div>
    <div class="panel"><div class="panel-head"><div><h2>${latestFailed ? '最近需要处理' : '工作台已就绪'}</h2><p>${latestFailed ? '优先修复最近一次失败。' : '从测试计划开始组织你的自动化。'}</p></div></div>${latestFailed ? diagnosticMini(latestFailed) : `<div class="empty"><h2>没有待处理失败</h2><p>运行测试计划后，失败用例会在这里给出原因和建议。</p></div>`}</div></div>`;
  $('#dashNewPlan').onclick = () => openPlanModal(); $('#allRuns').onclick = () => go('runs'); bindRunRows();
}
function emptyHtml(title, text) { return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(text)}</p></div>`; }
function diagnosticMini(run) { const diag = run.diagnostic || run.caseRuns?.find(x=>x.status==='failed')?.diagnostic; return `<div class="run-summary failure"><div class="split"><div><strong>${esc(run.caseName || run.planName || '执行失败')}</strong><p class="muted">${formatTime(run.startedAt)}</p></div>${statusBadge('failed')}</div><p>${esc(diag?.title || run.error || '有用例执行失败')}</p><button class="btn small secondary" data-run-open="${run.id}">查看诊断</button></div>`; }

function renderPlans() {
  pageHeading('测试计划'); $('#content').innerHTML = `<div class="hero"><div><h2>测试计划</h2><p>计划按顺序组织测试套件，套件再包含用例和生命周期。</p></div><button class="btn primary" id="pageNewPlan">新建计划</button></div><div class="plan-grid">${state.plans.map(plan => {const suites=(plan.suiteIds||[]).map(id=>state.suites.find(s=>s.id===id)).filter(Boolean);const count=suites.reduce((n,s)=>n+s.caseIds.length,0);return `<article class="plan-card" data-plan="${plan.id}"><h3>${esc(plan.name)}</h3><p>${esc(plan.description || '暂无计划说明')}</p><div class="plan-meta"><span>${suites.length} 个套件 · ${count} 个用例</span><span>更新于 ${formatTime(plan.updatedAt)}</span></div></article>`;}).join('') || emptyHtml('还没有测试计划','新建计划后，可以添加测试套件。')}</div>`;
  $('#pageNewPlan').onclick = () => openPlanModal(); $$('[data-plan]').forEach(node => node.onclick = () => go('plans', node.dataset.plan));
}
function renderPlanDetail() {
  const plan = state.plans.find(x => x.id === selectedPlanId); if (!plan) return go('plans'); const suites=(plan.suiteIds||[]).map(id=>state.suites.find(s=>s.id===id)).filter(Boolean); const cases=suites.flatMap(s=>s.caseIds).length;
  pageHeading(plan.name, '测试计划 / 详情'); $('#content').innerHTML = `<div class="panel summary-card"><div class="split"><div><h2>${esc(plan.name)}</h2><p>${esc(plan.description || '暂无说明')}</p></div><div class="actions"><button class="btn secondary" id="editPlan">编辑</button><button class="btn primary" id="runPlan" ${cases ? '' : 'disabled'}>运行整个计划</button><button class="btn danger" id="deletePlan">删除</button></div></div></div>
    <div id="planRunResult"></div><div class="panel"><div class="panel-head"><div><h2>计划中的测试套件</h2><p>执行顺序：Suite Setup → Case Setup/Steps/Teardown → Suite Teardown。</p></div><div class="actions"><button class="btn secondary" id="addExistingSuite">加入已有套件</button><button class="btn primary" id="createSuite">新建套件</button></div></div><div class="list">${suites.map(suiteRowHtml).join('') || emptyHtml('计划还是空的','新建或加入一个测试套件后即可运行。')}</div></div>`;
  $('#editPlan').onclick = () => openPlanModal(plan); $('#deletePlan').onclick = () => deletePlan(plan); $('#addExistingSuite').onclick = () => openAddSuite(plan); $('#createSuite').onclick = () => openSuiteModal(undefined,plan.id); $('#runPlan').onclick = () => runPlan(plan); bindSuiteRows();
}
function suiteRowHtml(suite){return `<article class="case-row" data-suite="${suite.id}"><div><h3>${esc(suite.name)}</h3><p>${suite.caseIds.length} 个用例 · Setup ${suite.setupSteps.length} 步 · Teardown ${suite.teardownSteps.length} 步</p></div><span class="badge visual">Suite</span><span class="muted">${suite.sessionPolicy==='shared-current-run'?'本次运行共享登录态':'每个用例全新会话'}</span></article>`;}
function bindSuiteRows(){$$('[data-suite]').forEach(node=>node.onclick=()=>go('suites',node.dataset.suite));}
function renderSuites(){pageHeading('测试套件');$('#content').innerHTML=`<div class="hero"><div><h2>测试套件</h2><p>把同领域用例组织在一起，并配置套件级 Setup、Teardown。</p></div><button class="btn primary" id="pageNewSuite">新建测试套件</button></div><div class="list">${state.suites.map(suiteRowHtml).join('')||emptyHtml('还没有测试套件','新建套件后配置登录和退出登录。')}</div>`;$('#pageNewSuite').onclick=()=>openSuiteModal();bindSuiteRows();}
function recordedSourcesHtml(sources={}){if(!sources.javascript&&!sources.python)return '';return `<details class="technical recorded-source"><summary>查看最近录制的代码</summary><div class="code-toolbar"><strong>JavaScript</strong></div><textarea class="code-editor" readonly>${esc(sources.javascript||'')}</textarea><div class="code-toolbar"><strong>Python</strong></div><textarea class="code-editor" readonly>${esc(sources.python||'')}</textarea></details>`;}
function lifecycleEditorHtml(owner,phase){const steps=owner[phase]||[];const title=phase==='setupSteps'?'Suite Setup':'Suite Teardown';return `<div class="lifecycle-help"><strong>${title}</strong><p>${phase==='setupSteps'?'在本次套件开始时执行，例如登录；产生的登录态只在本次运行内传给各用例。':'无论 Setup 或用例是否失败都会执行，例如退出登录和清理数据。'}</p></div><div id="suitePhaseResult"></div><div class="actions phase-actions"><button class="btn secondary" id="recordSuitePhase">录制此阶段</button><button class="btn secondary" id="runSuitePhase" ${steps.length?'':'disabled'}>回放此阶段</button><button class="btn secondary" id="insertSuiteFlow">插入公共流程</button><button class="btn primary" id="addSuiteStep">添加步骤</button></div><div id="steps" class="step-list">${steps.map(stepHtml).join('')||emptyHtml('还没有生命周期步骤','可以录制、添加普通步骤或插入公共流程。')}</div><div class="actions" style="margin-top:14px"><button class="btn primary" id="saveSuiteLifecycle">保存 ${title}</button></div>${recordedSourcesHtml(owner.sources?.[phase])}`;}
function renderSuiteDetail(){const suite=state.suites.find(x=>x.id===selectedSuiteId);if(!suite)return go('suites');const cases=suite.caseIds.map(id=>state.cases.find(c=>c.id===id)).filter(Boolean);pageHeading(suite.name,'测试套件 / 编辑');$('#content').innerHTML=`<div class="panel summary-card"><div class="split"><div><h2>${esc(suite.name)}</h2><p>${esc(suite.description||'暂无说明')}</p></div><div class="actions"><button class="btn secondary" id="editSuite">编辑</button><button class="btn primary" id="runSuite" ${cases.length?'':'disabled'}>运行套件</button><button class="btn danger" id="deleteSuite">删除</button></div></div></div><div id="suiteRunResult"></div><div class="panel"><div class="tabs"><button class="tab ${suitePhase==='setupSteps'?'active':''}" data-suite-phase="setupSteps">Suite Setup</button><button class="tab ${suitePhase==='teardownSteps'?'active':''}" data-suite-phase="teardownSteps">Suite Teardown</button><button class="tab ${suitePhase==='cases'?'active':''}" data-suite-phase="cases">测试用例</button></div>${suitePhase==='cases'?`<div class="panel-head"><div><h2>套件中的用例</h2><p>每个用例默认使用全新浏览器 Context。</p></div><button class="btn primary" id="addSuiteCase">加入用例</button></div><div class="list">${cases.map(caseRowHtml).join('')||emptyHtml('套件还没有用例','加入已有测试用例。')}</div>`:lifecycleEditorHtml(suite,suitePhase)}</div>`;$$('[data-suite-phase]').forEach(btn=>btn.onclick=()=>{suitePhase=btn.dataset.suitePhase;renderSuiteDetail();});$('#editSuite').onclick=()=>openSuiteModal(suite);$('#deleteSuite').onclick=()=>deleteSuite(suite);$('#runSuite').onclick=()=>runSuite(suite);if(suitePhase==='cases'){bindCaseRows();$('#addSuiteCase').onclick=()=>openAddCaseToSuite(suite);}else{bindSteps();$('#addSuiteStep').onclick=()=>appendStep();$('#recordSuitePhase').onclick=()=>openStructuredRecordDialog('suite',suite);$('#runSuitePhase').onclick=()=>runSuitePhase(suite);$('#insertSuiteFlow').onclick=()=>insertFlowCall();$('#saveSuiteLifecycle').onclick=()=>saveSuiteLifecycle(suite);} }
function caseRowHtml(testCase) { const last = state.runs.find(r => r.caseId === testCase.id); return `<article class="case-row" data-case="${testCase.id}"><div><h3>${esc(testCase.name)}</h3><p>${testCase.steps.length} 个步骤 · ${esc(testCase.defaults?.browser || 'chromium')}</p></div><span class="badge ${testCase.editorMode === 'code' ? 'code' : 'visual'}">${testCase.editorMode === 'code' ? '代码' : '无代码'}</span>${last ? statusBadge(last.status) : '<span class="muted">未执行</span>'}</article>`; }
function bindCaseRows() { $$('[data-case]').forEach(node => node.onclick = () => go('cases', node.dataset.case)); }
async function runPlan(plan) { const button = $('#runPlan'); button.disabled = true; button.textContent = '计划执行中…'; $('#planRunResult').innerHTML = '<div class="run-summary"><strong>正在逐个执行计划内用例，请不要关闭页面。</strong></div>'; try { const run = await api(`/api/plans/${plan.id}/run`, { method:'POST', body:JSON.stringify({ headless:false }) }); $('#planRunResult').innerHTML = planRunResultHtml(run); toast('测试计划执行完成'); } catch (error) { const run = error.payload; $('#planRunResult').innerHTML = run?.caseRuns ? planRunResultHtml(run) : `<div class="run-summary failure">${esc(error.message)}</div>`; toast('测试计划存在失败用例','error'); } finally { button.disabled=false; button.textContent='运行整个计划'; await refresh(true); } }
function planRunResultHtml(run) { return `<div class="run-summary ${run.status==='passed'?'success':'failure'}"><div class="split"><strong>${run.status==='passed'?'计划全部通过':'计划执行完成，存在失败'}</strong>${statusBadge(run.status)}</div><p>${run.summary?.passed || 0} 通过 · ${run.summary?.failed || 0} 失败 · ${formatDuration(run.durationMs)}</p><button class="btn small secondary" data-run-open="${run.id}">查看完整记录</button></div>`; }

function renderCases() {
  pageHeading('测试用例'); const orphans = state.cases.filter(c => !state.suites.some(s => s.caseIds.includes(c.id)));
  $('#content').innerHTML = `<div class="hero"><div><h2>测试用例</h2><p>无代码模式编辑步骤和期望值；代码模式在线编辑 Playwright JS/Python。</p></div><button class="btn primary" id="pageNewCase">新建测试用例</button></div><div class="panel"><div class="panel-head"><div><h2>全部用例</h2><p>${orphans.length} 个未加入测试计划。</p></div></div><div class="list">${state.cases.map(caseRowHtml).join('') || emptyHtml('还没有测试用例','选择无代码或代码模式创建第一个用例。')}</div></div>`;
  $('#pageNewCase').onclick = () => openCaseModal(); bindCaseRows();
}
function flowRowHtml(flow){return `<article class="case-row" data-flow="${flow.id}"><div><h3>${esc(flow.name)}</h3><p>v${flow.version} · ${flow.steps.length} 个步骤 · ${flow.parameters.length} 个参数</p></div><span class="badge ${flow.safety==='destructive'?'danger-text':'code'}">${flow.safety==='destructive'?'敏感操作':'公共流程'}</span><span class="muted">固定版本引用</span></article>`;}
function bindFlowRows(){$$('[data-flow]').forEach(node=>node.onclick=()=>go('flows',node.dataset.flow));}
function renderFlows(){pageHeading('公共流程');$('#content').innerHTML=`<div class="hero"><div><h2>公共流程</h2><p>复用登录、进入商品页、加购物车、支付、绑卡和退出登录等场景步骤。</p></div><button class="btn primary" id="pageNewFlow">新建公共流程</button></div><div class="list">${state.flows.map(flowRowHtml).join('')||emptyHtml('还没有公共流程','创建后可插入 Case 或 Suite 的任意生命周期阶段。')}</div>`;$('#pageNewFlow').onclick=()=>openFlowModal();bindFlowRows();}
function renderFlowDetail(){const flow=state.flows.find(x=>x.id===selectedFlowId);if(!flow)return go('flows');pageHeading(flow.name,'公共流程 / 编辑');$('#content').innerHTML=`<div class="panel summary-card"><div class="split"><div><h2>${esc(flow.name)} <span class="badge code">v${flow.version}</span></h2><p>${esc(flow.description||'暂无说明')}</p></div><div class="actions"><button class="btn secondary" id="recordFlow">录制公共流程</button><button class="btn primary" id="runFlow" ${flow.steps.length?'':'disabled'}>回放公共流程</button><button class="btn secondary" id="editFlow">编辑信息</button><button class="btn danger" id="deleteFlow">删除</button></div></div></div><div id="flowRunResult"></div><div class="panel"><div class="notice">用例会固定引用当前版本。修改或重新录制会创建新版本，旧用例继续使用原版本。${flow.safety==='destructive'?'<br><strong>敏感操作：</strong>支付、绑卡、下单类步骤禁止自动重试。':''}</div><div class="field full"><label>参数（JSON 数组）</label><textarea id="flowParameters">${esc(JSON.stringify(flow.parameters||[],null,2))}</textarea><small>示例：[{"name":"productId","required":true}]，调用时可传 ${'${data.productId}'}。</small></div><div class="panel-head"><div><h2>公共流程步骤</h2><p>录制后自动保存完整代码、Python 和可编辑的无代码步骤。</p></div><div class="actions"><button class="btn secondary" id="insertNestedFlow">插入其他公共流程</button><button class="btn primary" id="addFlowStep">添加步骤</button></div></div><div id="steps" class="step-list">${flow.steps.map(stepHtml).join('')||emptyHtml('还没有步骤','录制、添加普通步骤或引用其他公共流程。')}</div><div class="actions" style="margin-top:14px"><button class="btn primary" id="saveFlow">保存并创建新版本</button></div>${recordedSourcesHtml(flow.sources)}</div>`;bindSteps();$('#recordFlow').onclick=()=>openStructuredRecordDialog('flow',flow);$('#runFlow').onclick=()=>runFlow(flow);$('#editFlow').onclick=()=>openFlowModal(flow);$('#deleteFlow').onclick=()=>deleteFlow(flow);$('#addFlowStep').onclick=()=>appendStep();$('#insertNestedFlow').onclick=()=>insertFlowCall(flow.id);$('#saveFlow').onclick=()=>saveFlowSteps(flow);}
function optionList(values, selected) { const labels={none:'不额外等待',elementAuto:'自动等待本步骤元素（推荐）',elementVisible:'等待指定元素出现',elementHidden:'等待 Loading/遮罩消失',elementEnabled:'等待按钮可用',elementEditable:'等待输入框可编辑',elementText:'等待元素出现指定文本',url:'等待 URL 匹配',loadState:'等待页面加载阶段'};return values.map(value => `<option value="${value}" ${value===selected?'selected':''}>${labels[value]||value}</option>`).join(''); }
function advancedStepHtml(step, operation) {
  const ready=step.readiness||{type:'none'};const rp=step.retryPolicy||{maxAttempts:Number(step.retryCount||0)+1,baseDelayMs:1000,backoff:'fixed',recovery:'none',idempotency:'auto'};const rloc=ready.locator?.primary||{};const response=step.response||{};const configured=ready.type!=='none'||Number(rp.maxAttempts)>1||rp.recovery!=='none'||operation==='clickAndWaitForResponse';
  return `<details class="step-advanced" ${configured?'open':''}><summary>稳定性与高级等待${configured?' · 已配置':''}</summary><div class="advanced-grid"><label>执行前等待<select class="readinessType">${optionList(readinessTypes,ready.type||'none')}</select></label><label class="readyLocatorField">等待定位方式<select class="readyStrategy">${optionList(strategies,rloc.strategy||'testId')}</select></label><label class="readyLocatorField">等待元素<input class="readyLocator" value="${esc(rloc.value||'')}" placeholder="例如 loading-spinner"></label><label class="readyNameField">等待元素名称<input class="readyName" value="${esc(rloc.name||'')}"></label><label class="readyValueField">等待值<input class="readyValue" value="${esc(ready.value||'')}" placeholder="文本、URL 正则或 domcontentloaded"></label><label>等待超时(ms)<input class="readyTimeout" type="number" min="1" value="${Number(ready.timeoutMs||step.timeoutMs||10000)}"></label><label>最多尝试次数<select class="maxAttempts">${[1,2,3,4].map(n=>`<option value="${n}" ${Number(rp.maxAttempts||1)===n?'selected':''}>${n}</option>`).join('')}</select></label><label>重试间隔(ms)<input class="baseDelay" type="number" min="0" value="${Number(rp.baseDelayMs||1000)}"></label><label>等待策略<select class="backoff"><option value="fixed" ${rp.backoff!=='exponential'?'selected':''}>固定</option><option value="exponential" ${rp.backoff==='exponential'?'selected':''}>指数退避</option></select></label><label>失败恢复<select class="recovery"><option value="none" ${rp.recovery==='none'?'selected':''}>不恢复</option><option value="reload" ${rp.recovery==='reload'?'selected':''}>刷新页面</option><option value="reopen" ${rp.recovery==='reopen'?'selected':''}>重新打开当前 URL</option></select></label><label>重复操作安全性<select class="idempotency"><option value="auto" ${rp.idempotency==='auto'?'selected':''}>自动判断</option><option value="safe" ${rp.idempotency==='safe'?'selected':''}>可安全重复</option><option value="never" ${rp.idempotency==='never'?'selected':''}>禁止重复</option></select></label></div><div class="response-config ${operation==='clickAndWaitForResponse'?'':'hidden'}"><h4>点击并等待接口</h4><div class="advanced-grid"><label>接口 URL 包含<input class="responseUrl" value="${esc(response.urlPattern||'')}" placeholder="/api/search"></label><label>请求方法<select class="responseMethod">${optionList(['','GET','POST','PUT','PATCH','DELETE'],response.method||'')}</select></label><label>期望状态<input class="responseStatus" type="number" min="100" max="599" value="${Number(response.status||200)}"></label><label>接口超时(ms)<input class="responseTimeout" type="number" min="1" value="${Number(response.timeoutMs||30000)}"></label></div></div><p class="advanced-help">自动判断不会重复点击、提交等可能产生副作用的操作；确认操作可幂等后再选择“可安全重复”。</p></details>`;
}
function stepHtml(step = { kind:'action', action:'click', locator:{primary:{strategy:'role',value:'button',name:''}}, timeoutMs:10000, retryCount:0 }, index = 0) {
  const kind = step.kind || 'action'; if(kind==='flowCall'){const flow=state.flows.find(item=>item.id===step.flowId);return `<article class="step step-card flow-call" data-id="${esc(step.id||'')}"><span class="step-number">${index+1}</span><div><div class="step-fields flow-fields"><label>类型<select class="stepKind"><option value="action">操作</option><option value="assertion">断言</option><option value="flowCall" selected>公共流程</option></select></label><label>公共流程<select class="flowId">${state.flows.map(item=>`<option value="${item.id}" ${item.id===step.flowId?'selected':''}>${esc(item.name)} · v${item.version}</option>`).join('')}</select></label><label>固定版本<input class="flowVersion" type="number" min="1" value="${Number(step.flowVersion||flow?.version||1)}"></label><label class="full-field">参数 JSON<input class="flowParams" value="${esc(JSON.stringify(step.params||{}))}" placeholder='{"productId":"\${data.productId}"}'></label></div><p class="advanced-help">执行时展开为真实步骤；固定版本不会随公共流程更新。支付/绑卡等敏感流程禁止自动重试。</p></div><button class="btn danger small remove">删除</button></article>`;} const operation = kind === 'action' ? step.action : step.assertion; const p = step.locator?.primary || {}; const noLocator = ['goto','reload','back','forward','waitForURL','waitForLoadState','waitForTimeout','toHaveURL','toHaveTitle'].includes(operation); const value = step.url ?? step.value ?? step.expected ?? '';
  return `<article class="step step-card" data-id="${esc(step.id || '')}"><span class="step-number">${index+1}</span><div><div class="step-fields"><label>类型<select class="stepKind"><option value="action" ${kind==='action'?'selected':''}>操作</option><option value="assertion" ${kind==='assertion'?'selected':''}>断言</option><option value="flowCall">公共流程</option></select></label><label>操作 / 断言<select class="operation">${optionList(kind==='action'?actions:assertions,operation)}</select></label><label>定位方式<select class="strategy" ${noLocator?'disabled':''}>${optionList(strategies,p.strategy||'role')}</select></label><label>元素定位值<input class="locator" value="${esc(p.value||'')}" ${noLocator?'disabled':''} placeholder="例如 button 或 Email"></label><label>名称 / 输入 / 期望值<input class="value" value="${esc(value)}" placeholder="输入值、期望值或 URL"></label><label>步骤超时(ms)<input class="timeout" type="number" min="1" value="${Number(step.timeoutMs||10000)}"></label></div><div class="step-extra"><label class="role-name ${p.strategy==='role'&&!noLocator?'':'hidden'}">可访问名称 <input class="locatorName" value="${esc(p.name||'')}" placeholder="例如 登录"></label><label><input class="continueOnError" type="checkbox" ${step.continueOnError?'checked':''}> 失败后继续并记为警告</label>${operation==='goto'?`<label>期望 URL（可选）<input class="expectedUrl" value="${esc(step.expectedUrl||'')}" placeholder="login\\.coupang\\.com"></label>`:''}</div>${advancedStepHtml(step,operation)}</div><button class="btn danger small remove">删除</button></article>`;
}
function renderCaseEditor() {
  const testCase = state.cases.find(x => x.id === selectedCaseId); if (!testCase) return go('cases'); const suites=state.suites.filter(s=>s.caseIds.includes(testCase.id));const plans = state.plans.filter(p=>(p.suiteIds||[]).some(id=>suites.some(s=>s.id===id))); pageHeading(testCase.name,'测试用例 / 编辑');
  $('#content').innerHTML = `<div class="detail-layout"><div><div class="panel"><div class="panel-head"><div><h2>${esc(testCase.name)}</h2><p>版本 ${testCase.version} · ${plans.length ? plans.map(p=>esc(p.name)).join('、') : '未加入计划'}</p></div><div class="actions"><button class="btn secondary" id="startRecord">开始录制</button><button class="btn primary" id="runCase">回放用例</button></div></div><div class="tabs"><button class="tab ${caseTab==='visual'?'active':''}" data-tab="visual">无代码步骤</button><button class="tab ${caseTab==='code'?'active':''}" data-tab="code">代码编辑</button><button class="tab ${caseTab==='settings'?'active':''}" data-tab="settings">配置与数据</button></div><div id="caseTabBody">${caseTabBody(testCase)}</div></div><div id="runResult"></div></div>
    <aside><div class="panel"><div class="panel-head"><div><h2>用例状态</h2><p>所有数据只写入本机。</p></div></div><div class="field"><label>用例名称</label><input id="sideCaseName" value="${esc(testCase.name)}"></div><p class="muted">模式：${testCase.editorMode==='code'?'代码':'无代码'}<br>步骤：${testCase.steps.length}<br>浏览器：${esc(testCase.defaults.browser)}</p><button class="btn secondary" id="saveBasics">保存名称</button></div><div class="panel"><h2 class="section-title">本地文件</h2>${sourceFilesHtml(testCase)}<p class="muted">计划名是文件夹名；每个用例保存为一个 JavaScript 和一个 Python 文件。</p></div><div class="panel"><button class="btn danger" id="deleteCase">删除测试用例</button></div></aside></div>`;
  bindEditor(testCase);
}
function mappingRowHtml(rule={enabled:true,from:'',to:'',preservePath:true}){return `<div class="mapping-row"><label><input class="mappingEnabled" type="checkbox" ${rule.enabled!==false?'checked':''}> 启用</label><input class="mappingFrom" value="${esc(rule.from||'')}" placeholder="https://www.coupang.com/"><span>→</span><input class="mappingTo" value="${esc(rule.to||'')}" placeholder="https://qa-coupang.example/"><label><input class="mappingPreserve" type="checkbox" ${rule.preservePath!==false?'checked':''}> 保留后续路径</label><button class="btn danger small removeMapping" type="button">删除</button></div>`;}
function stabilitySettingsHtml(testCase){const s=testCase.defaults.stability||{};return `<div class="field full stability-card"><div><label>回放稳定性</label><small>使用明确的页面就绪信号和自动重试，不建议只增加固定延时。</small></div><select id="stabilityPreset"><option value="fast" ${s.preset==='fast'?'selected':''}>快速模式</option><option value="standard" ${!s.preset||s.preset==='standard'?'selected':''}>标准模式（推荐）</option><option value="slow" ${s.preset==='slow'?'selected':''}>慢速网络模式</option><option value="custom" ${s.preset==='custom'?'selected':''}>自定义</option></select><div class="stability-timeouts"><label>导航超时(ms)<input id="navigationTimeout" type="number" value="${Number(s.navigationTimeoutMs||30000)}"></label><label>操作超时(ms)<input id="actionTimeout" type="number" value="${Number(s.actionTimeoutMs||10000)}"></label><label>断言超时(ms)<input id="assertionTimeout" type="number" value="${Number(s.assertionTimeoutMs||10000)}"></label></div></div>`;}
function settingsTabHtml(testCase){const proxy=testCase.defaults.proxy||{};const mappings=proxy.mappings||[];const session=testCase.defaults.session||{mode:'clean'};return `<div class="field-grid"><div class="field full session-card"><div><label>浏览器会话隔离</label><small>默认每次录制和回放都清空 Cookie、缓存、Local/Session Storage 和 IndexedDB。</small></div><select id="sessionMode"><option value="clean" ${session.mode!=='persistent'?'selected':''}>全新会话（推荐）</option><option value="persistent" ${session.mode==='persistent'?'selected':''}>显式持久化登录态（高级）</option></select><button class="btn danger small" id="clearSessionState" type="button">删除历史登录态和缓存</button></div>${stabilitySettingsHtml(testCase)}<div class="field"><label>浏览器</label><select id="browser"><option value="chromium">Chrome / Chromium</option><option value="firefox">Firefox</option><option value="webkit">WebKit（非真实 Safari）</option></select></div><div class="field"><label>页面语言</label><input id="locale" value="${esc(testCase.defaults.locale||'zh-CN')}"></div><div class="field full"><label>起始 URL</label><input id="baseUrl" value="${esc(testCase.defaults.baseUrl||'')}" placeholder="https://example.com"></div><div class="field"><label>测试账号（名称/引用）</label><input id="accountRef" value="${esc(testCase.accountRef||'')}" placeholder="例如 coupay.qa-buyer"><small>仅用于标识执行账号，不会自动填写密码。</small></div><div class="field"><label>上游代理服务器（可选）</label><input id="proxy" value="${esc(proxy.server||'')}" placeholder="Charles: http://127.0.0.1:8888"></div><div class="field full"><label>代理绕过域名（逗号分隔）</label><input id="proxyBypass" value="${esc(proxy.bypass||'')}" placeholder="localhost,127.0.0.1,.corp.internal"></div><div class="field full"><label>测试数据 JSON</label><textarea id="data">${esc(JSON.stringify(testCase.data||{},null,2))}</textarea><small>无代码步骤可使用 ${'${data.searchText}'} 或嵌套 ${'${data.account.username}'}；密码推荐使用 ${'${env.COUPAY_PASSWORD}'}，避免写入文件。</small></div><div class="field full"><div class="split"><label>远程映射（Map Remote，可添加多条）</label><button class="btn small secondary" id="addMapping" type="button">添加映射</button></div><div id="proxyMappings" class="mapping-list">${mappings.map(mappingRowHtml).join('')||'<p class="muted mapping-empty">还没有映射规则。</p>'}</div><small>回放时按顺序匹配第一条规则。例如把 https://www.coupang.com/ 映射到 https://qa.example.com/。Playwright 原生映射要求协议一致；录制阶段或 HTTP↔HTTPS 请把上游代理设为 Charles，并在 Charles 的 Map Remote 中配置。</small></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="saveSettings">保存配置</button></div>`;}
function caseTabBody(testCase) {
  if (caseTab === 'code') return `<div class="notice"><strong>同步规则：</strong>保存无代码步骤会重新生成 JS/Python；保存 JavaScript 会把可识别的 Playwright 语句同步回无代码步骤并重新生成 Python。复杂自定义 JS 会完整保留但可能无法可视化。Python 是独立导出文件，保存 Python 不会反向覆盖其他版本。</div><div class="code-toolbar"><div class="inline"><button class="btn small ${codeLanguage==='javascript'?'primary':'secondary'}" data-language="javascript">JavaScript</button><button class="btn small ${codeLanguage==='python'?'primary':'secondary'}" data-language="python">Python</button></div><div class="actions"><button class="btn small secondary" id="generateCode">从步骤重新生成两种代码</button><button class="btn small primary" id="saveCode">保存代码到本地</button></div></div><textarea id="codeEditor" class="code-editor" spellcheck="false">${esc(testCase.sources?.[codeLanguage] || '')}</textarea>${sourceFilesHtml(testCase)}`;
  if (caseTab === 'settings') return settingsTabHtml(testCase);
  const phases={setup:'setupSteps',steps:'steps',teardown:'teardownSteps'};const list=testCase[phases[casePhase]]||[];const descriptions={setup:'用例开始前执行，例如进入商品详情页。',steps:'用例的核心操作和断言。',teardown:'无论前面成功失败都会执行，例如清空购物车。'};return `<div class="notice">每次回放使用全新会话。Case Teardown 即使 Setup 或主体失败也会执行。</div><div class="phase-tabs"><button class="phase-tab ${casePhase==='setup'?'active':''}" data-case-phase="setup">Case Setup <b>${testCase.setupSteps.length}</b></button><button class="phase-tab ${casePhase==='steps'?'active':''}" data-case-phase="steps">测试步骤 <b>${testCase.steps.length}</b></button><button class="phase-tab ${casePhase==='teardown'?'active':''}" data-case-phase="teardown">Case Teardown <b>${testCase.teardownSteps.length}</b></button></div><div class="panel-head"><div><h2>${casePhase==='setup'?'Case Setup':casePhase==='teardown'?'Case Teardown':'步骤与断言'}</h2><p>${descriptions[casePhase]}</p></div><div class="actions">${casePhase==='steps'?'<button class="btn secondary" id="importRecord">手工导入（备用）</button>':''}<button class="btn secondary" id="insertCaseFlow">插入公共流程</button><button class="btn primary" id="addStep">添加步骤</button></div></div><div id="steps" class="step-list">${list.map(stepHtml).join('') || emptyHtml('还没有步骤','添加普通步骤或插入公共流程。')}</div><div class="actions" style="margin-top:14px"><button class="btn primary" id="saveCase">保存当前阶段</button><span class="muted" id="status"></span></div>`;
}
function sourceFilesHtml(testCase) { const files = testCase.sourceFiles || []; return files.length ? `<div class="file-list">${files.map(file=>`${esc(file.plan)}<br>JS: ${esc(file.javascript)}<br>PY: ${esc(file.python)}`).join('<br>')}</div>` : '<p class="muted">保存或加入计划后生成文件路径。</p>'; }
function bindEditor(testCase) {
  $$('.tab').forEach(tab => tab.onclick = () => { caseTab = tab.dataset.tab; renderCaseEditor(); });
  $('#startRecord').onclick = () => openRecordDialog(testCase); $('#runCase').onclick = () => runCase(testCase); $('#deleteCase').onclick = () => deleteCase(testCase); $('#saveBasics').onclick = () => saveBasics(testCase);
  if (caseTab === 'visual') { $$('[data-case-phase]').forEach(btn=>btn.onclick=()=>{casePhase=btn.dataset.casePhase;renderCaseEditor();});$('#addStep').onclick=appendStep; $('#insertCaseFlow').onclick=()=>insertFlowCall(); if($('#importRecord'))$('#importRecord').onclick=()=>importRecord(testCase); $('#saveCase').onclick=()=>saveVisual(testCase); bindSteps(); }
  if (caseTab === 'settings') { $('#browser').value=testCase.defaults.browser||'chromium'; $('#saveSettings').onclick=()=>saveSettings(testCase);$('#clearSessionState').onclick=()=>clearSessionState(testCase);$('#stabilityPreset').onchange=applyStabilityPreset;$('#addMapping').onclick=()=>{const empty=$('.mapping-empty');if(empty)empty.remove();$('#proxyMappings').insertAdjacentHTML('beforeend',mappingRowHtml());bindMappingRows();};bindMappingRows(); }
  if (caseTab === 'code') { $$('[data-language]').forEach(btn=>btn.onclick=()=>{ codeLanguage=btn.dataset.language; renderCaseEditor(); }); $('#saveCode').onclick=()=>saveCode(testCase); $('#generateCode').onclick=()=>generateCode(testCase); if(!testCase.sources?.[codeLanguage]) ensureSource(testCase); }
}
function bindSteps(){ $$('.remove').forEach(btn=>btn.onclick=()=>{btn.closest('.step').remove(); renumberSteps();}); $$('.stepKind').forEach(s=>s.onchange=()=>replaceStep(s.closest('.step'))); $$('.operation,.strategy,.readinessType,.readyStrategy').forEach(s=>s.onchange=()=>updateStepControls(s.closest('.step'))); $$('.step').forEach(updateStepControls);enhanceWaitHelp(); }
function enhanceWaitHelp(){$$('.step-advanced').forEach(details=>{const summary=$('summary',details);summary.childNodes[0].nodeValue='页面加载与自动恢复';if($('.wait-explainer',details))return;const help=document.createElement('div');help.className='wait-explainer';help.innerHTML='<strong>怎么选择？</strong><span>点击和填写会自动等待本步骤元素；慢页面选“自动等待本步骤元素”。登录跳转选“等待 URL 匹配”；Loading 动画选“等待 Loading/遮罩消失”。DOM 已就绪（domcontentloaded）适合 Coupang，避免等待全部广告和图片。</span><details><summary>等待策略和重复操作安全性是什么？</summary><p>固定：每次间隔相同；指数退避：1s、2s、4s，适合慢网络。自动判断不会重试点击/提交；支付、绑卡、下单必须选“禁止重复”。</p></details>';summary.insertAdjacentElement('afterend',help);});}
function appendStep(step){const empty=$('#steps .empty');if(empty)empty.remove();$('#steps').insertAdjacentHTML('beforeend',stepHtml(step&&step.kind?step:undefined,$$('#steps .step').length));bindSteps();}
function insertFlowCall(excludeId){const choices=state.flows.filter(flow=>flow.id!==excludeId);if(!choices.length)return toast('请先创建公共流程','error');const node=modal(`<h2>插入公共流程</h2><div class="field-grid"><div class="field full"><label>选择流程</label><select id="callFlow">${choices.map(flow=>`<option value="${flow.id}">${esc(flow.name)} · v${flow.version}${flow.safety==='destructive'?' · 敏感操作':''}</option>`).join('')}</select></div><div class="field full"><label>参数 JSON</label><textarea id="callParams">{}</textarea></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="addFlowCall">插入</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#addFlowCall',node).onclick=()=>{let params;try{params=JSON.parse($('#callParams',node).value||'{}');}catch{return toast('参数不是有效 JSON','error');}const flow=state.flows.find(item=>item.id===$('#callFlow',node).value);node.remove();appendStep({id:crypto.randomUUID(),kind:'flowCall',flowId:flow.id,flowVersion:flow.version,params});};}
function bindMappingRows(){$$('.removeMapping').forEach(button=>button.onclick=()=>{button.closest('.mapping-row').remove();if(!$$('.mapping-row').length)$('#proxyMappings').innerHTML='<p class="muted mapping-empty">还没有映射规则。</p>';});}
function applyStabilityPreset(){const preset=$('#stabilityPreset').value;const values={fast:[15000,5000,5000],standard:[30000,10000,10000],slow:[60000,20000,20000]}[preset];if(values){$('#navigationTimeout').value=values[0];$('#actionTimeout').value=values[1];$('#assertionTimeout').value=values[2];}}
function collectMappings(){return $$('.mapping-row').map(row=>({id:row.dataset.id||crypto.randomUUID(),enabled:$('.mappingEnabled',row).checked,from:$('.mappingFrom',row).value.trim(),to:$('.mappingTo',row).value.trim(),preservePath:$('.mappingPreserve',row).checked})).filter(rule=>rule.from||rule.to);}
function renumberSteps(){ $$('#steps .step-number').forEach((node,i)=>node.textContent=i+1); }
function replaceStep(row){ const i=$$('#steps .step').indexOf(row); const kind=$('.stepKind',row).value;const flow=state.flows[0];row.outerHTML=stepHtml(kind==='flowCall'?{kind,flowId:flow?.id,flowVersion:flow?.version||1,params:{}}:{kind},i); bindSteps(); }
function updateStepControls(row){ if($('.stepKind',row)?.value==='flowCall')return;const op=$('.operation',row).value; const noLocator=['goto','reload','back','forward','waitForURL','waitForLoadState','waitForTimeout','toHaveURL','toHaveTitle'].includes(op); $('.strategy',row).disabled=noLocator; $('.locator',row).disabled=noLocator; $('.role-name',row).classList.toggle('hidden',noLocator||$('.strategy',row).value!=='role');$('.response-config',row).classList.toggle('hidden',op!=='clickAndWaitForResponse');const ready=$('.readinessType',row).value;const readyHasLocator=ready.startsWith('element')&&ready!=='elementAuto';$$('.readyLocatorField',row).forEach(x=>x.classList.toggle('hidden',!readyHasLocator));$('.readyNameField',row).classList.toggle('hidden',!readyHasLocator||$('.readyStrategy',row).value!=='role');$('.readyValueField',row).classList.toggle('hidden',!['elementText','url','loadState'].includes(ready)); }
function collectSteps(source={steps:[]}){ return $$('#steps .step').map((row,index)=>{ const kind=$('.stepKind',row).value;if(kind==='flowCall'){let params;try{params=JSON.parse($('.flowParams',row).value||'{}');}catch{throw new Error(`第 ${index+1} 步公共流程参数不是有效 JSON`);}return{id:row.dataset.id||crypto.randomUUID(),kind,flowId:$('.flowId',row).value,flowVersion:Number($('.flowVersion',row).value||1),params};} const op=$('.operation',row).value; const value=$('.value',row).value; const noLocator=$('.locator',row).disabled; const timeoutMs=Number($('.timeout',row).value||10000); const step={id:row.dataset.id||source.steps?.[index]?.id||crypto.randomUUID(),kind,timeoutMs,continueOnError:$('.continueOnError',row).checked}; if(kind==='action'){step.action=op;if(op==='goto'){step.url=value;step.expectedUrl=$('.expectedUrl',row)?.value||'';}else step.value=value;}else{step.assertion=op;step.expected=value;} if(!noLocator)step.locator={primary:{strategy:$('.strategy',row).value,value:$('.locator',row).value,...($('.strategy',row).value==='role'&&$('.locatorName',row).value?{name:$('.locatorName',row).value}:{})}};const readyType=$('.readinessType',row).value;if(readyType!=='none'){const readiness={type:readyType,value:$('.readyValue',row).value,timeoutMs:Number($('.readyTimeout',row).value||timeoutMs)};if(readyType.startsWith('element'))readiness.locator={primary:{strategy:$('.readyStrategy',row).value,value:$('.readyLocator',row).value,...($('.readyStrategy',row).value==='role'&&$('.readyName',row).value?{name:$('.readyName',row).value}:{})}};step.readiness=readiness;}step.retryPolicy={maxAttempts:Number($('.maxAttempts',row).value||1),baseDelayMs:Number($('.baseDelay',row).value||0),backoff:$('.backoff',row).value,recovery:$('.recovery',row).value,idempotency:$('.idempotency',row).value};step.retryCount=Math.max(0,step.retryPolicy.maxAttempts-1);if(op==='clickAndWaitForResponse')step.response={urlPattern:$('.responseUrl',row).value,method:$('.responseMethod',row).value,status:Number($('.responseStatus',row).value||0),timeoutMs:Number($('.responseTimeout',row).value||timeoutMs)};return step; }); }
async function updateCase(testCase, patch, message='已保存'){ try { const saved=await api(`/api/cases/${testCase.id}`,{method:'PUT',body:JSON.stringify({...testCase,...patch})}); selectedCaseId=saved.id; toast(message); await refresh(); return saved; } catch(error){ if(error.code==='VERSION_CONFLICT') await refresh(); toast(error.message,'error'); throw error; } }
async function saveVisual(testCase){ try{if(testCase.editorMode==='code'&&casePhase==='steps'&&!confirm('保存主体无代码步骤会覆盖复杂自定义代码，是否继续？'))return;const key={setup:'setupSteps',steps:'steps',teardown:'teardownSteps'}[casePhase];await updateCase(testCase,{[key]:collectSteps({steps:testCase[key]}),...(casePhase==='steps'?{editorMode:'visual',regenerateSources:true}:{regenerateSources:true})},'生命周期步骤已保存，JS/Python 已自动同步');}catch(error){toast(error.message,'error');} }
async function saveBasics(testCase){ await updateCase(testCase,{name:$('#sideCaseName').value.trim()||'未命名用例'},'用例名称已保存'); }
async function saveSettings(testCase){ let data;try{data=JSON.parse($('#data').value||'{}');}catch{return toast('测试数据不是有效 JSON','error');} await updateCase(testCase,{accountRef:$('#accountRef').value.trim(),data,defaults:{...testCase.defaults,browser:$('#browser').value,locale:$('#locale').value.trim()||'zh-CN',baseUrl:$('#baseUrl').value.trim(),session:{...testCase.defaults.session,mode:$('#sessionMode').value},stability:{preset:$('#stabilityPreset').value,navigationTimeoutMs:Number($('#navigationTimeout').value||30000),actionTimeoutMs:Number($('#actionTimeout').value||10000),assertionTimeoutMs:Number($('#assertionTimeout').value||10000)},proxy:{...testCase.defaults.proxy,mode:$('#proxy').value.trim()?'proxy':'direct',server:$('#proxy').value.trim(),bypass:$('#proxyBypass').value.trim(),mappings:collectMappings()}}},'稳定性、会话隔离、配置、测试数据和代理映射已保存'); }
async function clearSessionState(testCase){if(!confirm('删除该用例保存的全部 Cookie、登录状态和浏览器 Profile？'))return;await api(`/api/cases/${testCase.id}/session-state`,{method:'DELETE'});toast('历史登录态和缓存已删除');}
async function saveCode(testCase){ try{const saved=await api(`/api/cases/${testCase.id}/source`,{method:'PUT',body:JSON.stringify({language:codeLanguage,code:$('#codeEditor').value})});const sync=saved.sync;if(sync?.warning)toast(sync.warning,'error');else if(codeLanguage==='javascript')toast(`JavaScript 已保存，并同步 ${sync?.stepCount||0} 个无代码步骤和 Python`);else toast('Python 已独立保存；不会反向覆盖 JS/无代码步骤');await refresh();}catch(error){toast(error.message,'error');} }
async function ensureSource(testCase){const editor=$('#codeEditor');editor.disabled=true;editor.value='正在根据当前步骤生成代码…';try{await api(`/api/cases/${testCase.id}/generate-source`,{method:'POST'});await refresh();}catch(error){editor.value='';editor.disabled=false;toast(error.message,'error');}}
async function generateCode(testCase){ if(!confirm('将根据当前无代码步骤覆盖 JavaScript 和 Python 源码，是否继续？'))return;try{await api(`/api/cases/${testCase.id}/generate-source`,{method:'POST'});toast('两种代码已重新生成');await refresh();}catch(error){toast(error.message,'error');} }

function openRecordDialog(testCase){let selected=testCase.compliance?.enabled?'compliance':'standard';const persistent=testCase.defaults.session?.mode==='persistent';const node=modal(`<h2>选择录制方式</h2><p class="muted">合规录制适用于已授权的企业测试环境和需要手工登录验证的站点。</p><div class="record-mode-grid"><button class="record-mode ${selected==='standard'?'selected':''}" data-mode="standard"><strong>标准录制</strong><span>Playwright 浏览器 · 全新临时会话</span></button><button class="record-mode ${selected==='compliance'?'selected':''}" data-mode="compliance"><strong>合规录制</strong><span>本机正式 Chrome · ${persistent?'显式持久化登录态':'独立临时 Profile'}</span></button></div><div id="recordCompliance" class="record-compliance ${selected==='compliance'?'':'hidden'}"><p>遇到 CAPTCHA 或登录验证时，直接在 Chrome 中手工完成后继续操作。平台会等待，不会破解验证或伪造指纹。</p><label class="check-row"><input id="recordPolicy" type="checkbox" ${testCase.compliance?.policyConfirmed?'checked':''}> 我确认目标环境和测试账号已获授权</label></div><div class="actions" style="margin-top:18px"><button class="btn primary" id="confirmRecord">打开录制浏览器</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$$('[data-mode]',node).forEach(button=>button.onclick=()=>{selected=button.dataset.mode;$$('[data-mode]',node).forEach(x=>x.classList.toggle('selected',x===button));$('#recordCompliance',node).classList.toggle('hidden',selected!=='compliance');});$('#confirmRecord',node).onclick=()=>startRecording(testCase,selected==='compliance',$('#recordPolicy',node)?.checked,node);}
async function startRecording(testCase,complianceMode,policyConfirmed,node){const button=$('#confirmRecord',node);if(complianceMode&&!policyConfirmed)return toast('请先确认目标环境和账号已获授权','error');button.disabled=true;button.textContent='正在打开…';try{const result=await api(`/api/cases/${testCase.id}/record`,{method:'POST',body:JSON.stringify({browser:testCase.defaults.browser,url:testCase.defaults.baseUrl,locale:testCase.defaults.locale,proxy:testCase.defaults.proxy,complianceMode,policyConfirmed,persistSession:testCase.defaults.session?.mode==='persistent'})});node.remove();showRecordingStatus(result,complianceMode,'#runResult');toast(result.message);if(result.status==='waiting-for-user')pollTargetRecording({type:'case',selector:'#runResult'},result.id);}catch(error){button.disabled=false;button.textContent='打开录制浏览器';toast(error.message,'error');}}
function showRecordingStatus(session,complianceMode=session.complianceMode,selector='#runResult'){const target=$(selector);if(!target)return;const terminal=['completed','failed','canceled'].includes(session.status);const awaiting=session.status==='awaiting-overwrite-confirmation';target.innerHTML=`<div class="run-summary compliance-session ${session.status==='failed'?'failure':''}"><div class="split"><strong>${session.status==='completed'?'录制已自动导入':session.status==='failed'?'录制处理失败':session.status==='canceled'?'已取消覆盖':awaiting?'等待确认覆盖':complianceMode?'合规录制进行中':'录制进行中'}</strong><span class="status ${session.status==='failed'?'failed':session.status==='completed'?'passed':'running'}">${session.status==='completed'?'已完成':session.status==='failed'?'失败':session.status==='canceled'?'已取消':awaiting?'待确认':'等待用户'}</span></div><p>${esc(session.message)}</p>${!terminal&&!awaiting?`<p><strong>正确结束方式：</strong>完成操作后关闭 Playwright Inspector。无需点击 Save；平台随后自动导入 JavaScript、Python 和无代码步骤。</p>`:''}${complianceMode&&session.profile?`<ul><li>独立测试 Profile：<code>${esc(session.profile)}</code></li><li>Cookie/登录状态：<code>${esc(session.loginState)}</code></li></ul>`:''}</div>`;}
async function pollTargetRecording(target,sessionId,attempt=0){if(attempt>3600)return toast('录制超过两小时，已停止自动等待。','error');await new Promise(resolve=>setTimeout(resolve,2000));let session;try{session=await api(`/api/recording-sessions/${sessionId}`);}catch(error){return toast(`读取录制状态失败：${error.message}`,'error');}showRecordingStatus(session,session.complianceMode,target.selector);if(session.status==='awaiting-overwrite-confirmation'){const overwrite=confirm(`${session.message}\n\n确认后会同时覆盖完整代码、Python 和无代码步骤。是否继续？`);session=await api(`/api/recording-sessions/${sessionId}/confirm-import`,{method:'POST',body:JSON.stringify({overwrite})});showRecordingStatus(session,session.complianceMode,target.selector);if(session.status==='canceled')return toast('已取消覆盖，原数据保持不变');}
  if(session.status==='completed'){if(target.type==='case'){codeLanguage='javascript';caseTab='code';toast('代码、Python 和无代码步骤已自动导入');}else toast('录制已导入代码和无代码步骤');await refresh();return;}if(session.status==='failed'){toast(session.message,'error');return;}pollTargetRecording(target,sessionId,attempt+1);}
async function importRecord(testCase){ try{const files=await api('/api/recordings');if(!files.length)return toast('尚未找到录制文件，请先完成一次录制。','error');const file=await chooseRecording(files);if(!file)return;if(testCase.steps.length&&!confirm(`将用 ${file.name} 覆盖当前 ${testCase.steps.length} 个步骤，是否继续？`))return;await api(`/api/cases/${testCase.id}/import-codegen`,{method:'POST',body:JSON.stringify({filename:file.name,mode:'replace'})});toast('录制已完整导入代码编辑器，并同步生成 Python');codeLanguage='javascript';caseTab='code';await refresh();}catch(error){toast(error.message,'error');} }
function chooseRecording(files){return new Promise(resolve=>{const node=modal(`<h2>选择录制文件</h2><p class="muted">按保存时间从新到旧排列。导入后仍可编辑步骤和期望值。</p><div class="list">${files.map(file=>`<button class="case-row" data-recording="${esc(file.name)}"><div><h3>${esc(file.name)}</h3><p>${formatTime(file.modifiedAt)} · ${file.size} B</p></div><span class="badge code">JS</span></button>`).join('')}</div><div class="actions" style="margin-top:16px"><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>{node.remove();resolve(null)};$$('[data-recording]',node).forEach(btn=>btn.onclick=()=>{node.remove();resolve(files.find(x=>x.name===btn.dataset.recording));});});}
async function runCase(testCase){ const button=$('#runCase');button.disabled=true;button.textContent='回放中…';$('#runResult').innerHTML='<div class="run-summary"><strong>正在执行浏览器步骤并采集证据…</strong></div>';try{const run=await api(`/api/cases/${testCase.id}/run`,{method:'POST',body:JSON.stringify({headless:false,data:testCase.data,browser:testCase.defaults.browser,proxy:testCase.defaults.proxy})});$('#runResult').innerHTML=runResultHtml(run);toast('用例回放通过');}catch(error){const run=error.payload;$('#runResult').innerHTML=run?.status?runResultHtml(run):`<div class="run-summary failure"><strong>无法开始回放</strong><p>${esc(error.message)}</p></div>`;if(run?.failedStepIndex>=0&&caseTab==='visual'){$$('#steps .step')[run.failedStepIndex]?.classList.add('failed-step');}toast('用例回放失败，请查看诊断','error');}finally{button.disabled=false;button.textContent='回放用例';await refresh(true);bindRunRows();} }
function runResultHtml(run){if(run.status==='passed'){const recovered=(run.steps||[]).filter(x=>x.recovered||x.navigationRecovered);return `<div class="run-summary success ${run.flaky?'flaky':''}"><div class="split"><strong>${run.flaky?'回放通过，但发生过自动恢复':'回放通过'}</strong>${statusBadge('passed')}</div><p>${(run.steps||[]).filter(x=>x.status==='passed').length} 个步骤通过 · ${formatDuration(run.durationMs)}${recovered.length?` · ${recovered.length} 个步骤自动恢复后通过`:''}</p><p class="muted">会话：${run.sessionIsolation==='suite-setup-snapshot'?'仅使用本次 Suite Setup 登录态':'全新浏览器会话，不继承上次 Cookie 或缓存'}</p>${recovered.length?`<details class="technical"><summary>查看恢复过程</summary><pre>${esc(JSON.stringify(recovered.map(x=>({step:x.index+1,phase:x.phase,operation:x.operation,actualUrl:x.actualUrl,attempts:x.attemptLog})),null,2))}</pre></details>`:''}${artifactLinks(run)}</div>`;}const d=run.diagnostic||{};return `<div class="run-summary failure"><div class="split"><div><strong>${esc(d.title||'用例执行失败')}</strong><p class="muted">失败阶段 ${esc(d.phase||'steps')} · 步骤 ${Number(run.failedStepIndex)+1} / ${(run.steps||[]).length}</p></div>${statusBadge('failed')}</div><div class="diagnostic"><div class="diagnostic-box"><span>发生了什么</span><strong>${esc(d.category||'执行失败')}</strong><p>${esc(d.cause||run.error)}</p><p><strong>实际页面：</strong>${esc(d.pageUrl||'未知')}</p></div><div class="diagnostic-box"><span>建议处理</span><p>${esc(d.suggestion||'检查截图和步骤配置后重试。')}</p></div></div>${d.networkIssues?.length?`<details class="technical"><summary>最近网络异常</summary><pre>${esc(JSON.stringify(d.networkIssues,null,2))}</pre></details>`:''}${artifactLinks(run)}<details class="technical"><summary>技术详情（给开发人员）</summary><pre>${esc(d.technical||run.error)}</pre></details></div>`;}
function artifactLinks(run){const a=run.artifacts||{};return `<div class="artifact-links">${a.screenshot?`<a class="btn small secondary" href="${a.screenshot}" target="_blank">查看失败截图</a>`:''}${a.video?`<a class="btn small secondary" href="${a.video}" target="_blank">查看录像</a>`:''}${a.trace?`<a class="btn small secondary" href="${a.trace}" target="_blank">下载 Trace</a>`:''}</div>`;}

function runRowHtml(run){const scope={plan:'测试计划',suite:'测试套件',case:'测试用例','suite-phase':'Suite 阶段',flow:'公共流程'}[run.scope]||run.scope;return `<article class="run-row" data-run-open="${run.id}"><div class="run-name"><strong>${esc(run.flowName||run.caseName||run.suiteName||run.planName||'执行记录')}</strong><small>${scope} · ${formatTime(run.startedAt)}</small></div>${statusBadge(run.status)}<span class="muted">${run.summary?`${run.summary?.passed||0}/${run.summary?.total||0} 通过`:`${run.steps?.length||0} 步骤`}</span><span class="muted">${formatDuration(run.durationMs)}</span><button class="btn small secondary">详情</button></article>`;}
function bindRunRows(){$$('[data-run-open]').forEach(node=>node.onclick=event=>{event.stopPropagation();openRun(node.dataset.runOpen);});}
function renderRuns(){pageHeading('执行记录');$('#content').innerHTML=`<div class="hero"><div><h2>执行记录</h2><p>查询用例、Suite 阶段、公共流程、套件和计划执行，查看失败证据。</p></div><button class="btn danger" id="clearRuns" ${state.runs.length?'':'disabled'}>清空记录</button></div><div class="panel"><div class="panel-head"><div><h2>历史执行</h2><p>记录元数据可删除；artifact 文件不会自动清理，避免误删证据。</p></div><div class="filters"><select id="statusFilter"><option value="">全部状态</option><option value="passed">通过</option><option value="failed">失败</option></select><select id="scopeFilter"><option value="">全部类型</option><option value="case">用例</option><option value="suite-phase">Suite 阶段</option><option value="flow">公共流程</option><option value="suite">套件</option><option value="plan">计划</option></select></div></div><div id="runList" class="list">${state.runs.map(runRowHtml).join('')||emptyHtml('还没有执行记录','从测试用例、Suite 阶段、公共流程、套件或计划发起回放。')}</div></div>`;bindRunRows();$('#statusFilter').onchange=$('#scopeFilter').onchange=filterRuns;$('#clearRuns').onclick=clearRuns;}
function filterRuns(){const status=$('#statusFilter').value,scope=$('#scopeFilter').value;const runs=state.runs.filter(r=>(!status||r.status===status)&&(!scope||r.scope===scope));$('#runList').innerHTML=runs.map(runRowHtml).join('')||emptyHtml('没有匹配记录','请调整筛选条件。');bindRunRows();}
async function openRun(id){const run=state.runs.find(x=>x.id===id)||await api(`/api/runs/${id}`);const suites=run.scope==='plan'?(run.suiteRuns||[]):run.scope==='suite'?[run]:[];const hierarchy=suites.length?`<div class="list" style="margin-top:16px">${suites.map(suite=>`<div class="run-summary ${suite.status==='passed'?'success':'failure'}"><div class="split"><strong>${esc(suite.suiteName)}</strong>${statusBadge(suite.status)}</div><p>Suite Setup: ${suite.setupRun?.status||'未配置'} · Case: ${suite.summary?.passed||0} 通过/${suite.summary?.failed||0} 失败/${suite.summary?.skipped||0} 跳过 · Suite Teardown: ${suite.teardownRun?.status||'未配置'}</p>${(suite.caseRuns||[]).map(child=>`<details><summary>${esc(child.caseName)} · ${child.status}</summary>${runResultHtml(child)}</details>`).join('')}${suite.setupRun?.status==='failed'?runResultHtml(suite.setupRun):''}${suite.teardownRun?.status==='failed'?runResultHtml(suite.teardownRun):''}</div>`).join('')}</div>`:runResultHtml(run);const node=modal(`<div class="split"><div><h2>${esc(run.flowName||run.caseName||run.suiteName||run.planName||'执行详情')}</h2><p class="muted">${formatTime(run.startedAt)} · ${formatDuration(run.durationMs)}</p></div>${statusBadge(run.status)}</div>${hierarchy}<div class="actions" style="margin-top:16px"><button class="btn danger" id="deleteRun">删除这条记录</button><button class="btn secondary" data-close>关闭</button></div>`,true);$('[data-close]',node).onclick=()=>node.remove();$('#deleteRun',node).onclick=async()=>{if(confirm('删除这条执行记录？截图、录像和 Trace 文件会保留。')){await api(`/api/runs/${run.id}`,{method:'DELETE'});node.remove();toast('执行记录已删除');await refresh();}};}
async function clearRuns(){if(!confirm('清空所有执行记录？截图、录像和 Trace 文件会保留。'))return;await api('/api/runs',{method:'DELETE'});toast('执行记录已清空');await refresh();}

function modal(content,wide=false){const node=document.createElement('div');node.className='modal';node.innerHTML=`<div class="modal-card ${wide?'wide':''}">${content}</div>`;document.body.append(node);node.onclick=e=>{if(e.target===node)node.remove();};return node;}
function openSuiteModal(suite,planId){const node=modal(`<h2>${suite?'编辑':'新建'}测试套件</h2><p class="muted">套件组织同领域用例，并提供 Setup/Teardown。</p><div class="field-grid"><div class="field full"><label>套件名称</label><input id="mSuiteName" value="${esc(suite?.name||'')}"></div><div class="field full"><label>套件说明</label><textarea id="mSuiteDesc">${esc(suite?.description||'')}</textarea></div><div class="field full"><label>会话策略</label><select id="mSuitePolicy"><option value="clean-per-case">每个用例全新会话（推荐）</option><option value="shared-current-run">只共享本次 Suite Setup 登录态</option></select></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="mSuiteSave">保存</button><button class="btn secondary" data-close>取消</button></div>`);if(suite)$('#mSuitePolicy',node).value=suite.sessionPolicy;$('[data-close]',node).onclick=()=>node.remove();$('#mSuiteSave',node).onclick=async()=>{try{const body={name:$('#mSuiteName',node).value.trim()||'新测试套件',description:$('#mSuiteDesc',node).value.trim(),sessionPolicy:$('#mSuitePolicy',node).value,...(suite?{caseIds:suite.caseIds,setupSteps:suite.setupSteps,teardownSteps:suite.teardownSteps}:{planId})};const saved=await api(suite?`/api/suites/${suite.id}`:'/api/suites',{method:suite?'PUT':'POST',body:JSON.stringify(body)});node.remove();selectedSuiteId=saved.id;view='suites';toast('测试套件已保存');await refresh();}catch(error){toast(error.message,'error');}};}
function openAddSuite(plan){const candidates=state.suites.filter(s=>!(plan.suiteIds||[]).includes(s.id));const node=modal(`<h2>加入已有测试套件</h2><div class="list">${candidates.map(suiteRowHtml).join('')||emptyHtml('没有可加入的套件','请先新建测试套件。')}</div><div class="actions" style="margin-top:16px"><button class="btn secondary" data-close>关闭</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$$('[data-suite]',node).forEach(item=>item.onclick=async()=>{await api(`/api/plans/${plan.id}/suites/${item.dataset.suite}`,{method:'POST'});node.remove();toast('套件已加入计划');await refresh();});}
function openAddCaseToSuite(suite){const candidates=state.cases.filter(c=>!suite.caseIds.includes(c.id));const node=modal(`<h2>加入已有测试用例</h2><div class="list">${candidates.map(caseRowHtml).join('')||emptyHtml('没有可加入的用例','请先新建一个测试用例。')}</div><div class="actions" style="margin-top:16px"><button class="btn secondary" data-close>关闭</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$$('[data-case]',node).forEach(item=>item.onclick=async()=>{await api(`/api/suites/${suite.id}/cases/${item.dataset.case}`,{method:'POST'});node.remove();toast('用例已加入套件');await refresh();});}
async function saveSuiteLifecycle(suite){try{await api(`/api/suites/${suite.id}`,{method:'PUT',body:JSON.stringify({...suite,[suitePhase]:collectSteps({steps:suite[suitePhase]})})});toast('Suite 生命周期已保存');await refresh();}catch(error){toast(error.message,'error');}}
function openStructuredRecordDialog(type,owner){const isSuite=type==='suite';const title=isSuite?(suitePhase==='setupSteps'?'Suite Setup':'Suite Teardown'):'公共流程';const node=modal(`<h2>录制 ${title}</h2><p class="muted">关闭 Inspector 后自动导入 JavaScript、Python 和无代码步骤。已有步骤不会直接覆盖，平台会再次请求确认。</p><div class="field-grid"><div class="field full"><label>起始 URL（可选）</label><input id="structuredUrl" placeholder="https://qa.example.com"></div><div class="field full"><label>浏览器</label><select id="structuredBrowser"><option value="chromium">Chrome / Chromium</option><option value="firefox">Firefox</option><option value="webkit">WebKit</option></select></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="startStructuredRecord">打开录制浏览器</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#startStructuredRecord',node).onclick=async()=>{const button=$('#startStructuredRecord',node);button.disabled=true;try{const phase=suitePhase==='setupSteps'?'setup':'teardown';const path=isSuite?`/api/suites/${owner.id}/phases/${phase}/record`:`/api/flows/${owner.id}/record`;const session=await api(path,{method:'POST',body:JSON.stringify({url:$('#structuredUrl',node).value.trim(),browser:$('#structuredBrowser',node).value})});node.remove();const selector=isSuite?'#suitePhaseResult':'#flowRunResult';showRecordingStatus(session,false,selector);pollTargetRecording({type,selector},session.id);}catch(error){button.disabled=false;toast(error.message,'error');}};}
async function runSuitePhase(suite){const phase=suitePhase==='setupSteps'?'setup':'teardown';const button=$('#runSuitePhase');button.disabled=true;button.textContent='回放中…';try{const run=await api(`/api/suites/${suite.id}/phases/${phase}/run`,{method:'POST',body:JSON.stringify({headless:false})});$('#suitePhaseResult').innerHTML=runResultHtml(run);toast(`${phase==='setup'?'Suite Setup':'Suite Teardown'} 回放通过`);}catch(error){$('#suitePhaseResult').innerHTML=error.payload?.status?runResultHtml(error.payload):`<div class="run-summary failure">${esc(error.message)}</div>`;toast('Suite 阶段回放失败','error');}finally{button.disabled=false;button.textContent='回放此阶段';await refresh(true);}}
async function runSuite(suite){const button=$('#runSuite');button.disabled=true;button.textContent='套件执行中…';try{const run=await api(`/api/suites/${suite.id}/run`,{method:'POST',body:JSON.stringify({headless:false})});$('#suiteRunResult').innerHTML=suiteRunResultHtml(run);toast('测试套件执行完成');}catch(error){$('#suiteRunResult').innerHTML=error.payload?.scope==='suite'?suiteRunResultHtml(error.payload):`<div class="run-summary failure">${esc(error.message)}</div>`;toast('测试套件执行失败','error');}finally{button.disabled=false;button.textContent='运行套件';await refresh(true);}}
function suiteRunResultHtml(run){return `<div class="run-summary ${run.status==='passed'?'success':'failure'}"><div class="split"><strong>${run.status==='passed'?'套件全部通过':'套件执行失败'}</strong>${statusBadge(run.status)}</div><p>Setup ${run.setupRun?.status||'未配置'} · Case ${run.summary?.passed||0} 通过/${run.summary?.failed||0} 失败/${run.summary?.skipped||0} 跳过 · Teardown ${run.teardownRun?.status||'未配置'}</p></div>`;}
async function deleteSuite(suite){if(!confirm(`删除测试套件“${suite.name}”？其中测试用例不会删除。`))return;await api(`/api/suites/${suite.id}`,{method:'DELETE'});selectedSuiteId=undefined;toast('测试套件已删除');await refresh();}
function openFlowModal(flow){const node=modal(`<h2>${flow?'编辑':'新建'}公共流程</h2><div class="field-grid"><div class="field full"><label>流程名称</label><input id="mFlowName" value="${esc(flow?.name||'')}"></div><div class="field full"><label>流程说明</label><textarea id="mFlowDesc">${esc(flow?.description||'')}</textarea></div><div class="field full"><label>安全级别</label><select id="mFlowSafety"><option value="normal">普通流程</option><option value="destructive">敏感操作：支付/绑卡/下单（禁止自动重试）</option></select></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="mFlowSave">保存</button><button class="btn secondary" data-close>取消</button></div>`);if(flow)$('#mFlowSafety',node).value=flow.safety;$('[data-close]',node).onclick=()=>node.remove();$('#mFlowSave',node).onclick=async()=>{const body={name:$('#mFlowName',node).value.trim()||'新公共流程',description:$('#mFlowDesc',node).value.trim(),safety:$('#mFlowSafety',node).value,...(flow?{steps:flow.steps,parameters:flow.parameters}:{steps:[],parameters:[]})};const saved=await api(flow?`/api/flows/${flow.id}`:'/api/flows',{method:flow?'PUT':'POST',body:JSON.stringify(body)});node.remove();selectedFlowId=saved.id;view='flows';toast('公共流程已保存');await refresh();};}
async function saveFlowSteps(flow){try{let parameters=JSON.parse($('#flowParameters').value||'[]');if(!Array.isArray(parameters))throw new Error('参数必须是 JSON 数组');const saved=await api(`/api/flows/${flow.id}`,{method:'PUT',body:JSON.stringify({...flow,parameters,steps:collectSteps({steps:flow.steps})})});toast(`公共流程已保存为 v${saved.version}`);await refresh();}catch(error){toast(error.message,'error');}}
async function runFlow(flow){const node=modal(`<h2>回放公共流程</h2><p class="muted">为流程参数填写本次测试数据，格式为 JSON 对象。</p><div class="field full"><label>测试数据 JSON</label><textarea id="flowRunData">{}</textarea></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="confirmRunFlow">开始回放</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#confirmRunFlow',node).onclick=async()=>{let data;try{data=JSON.parse($('#flowRunData',node).value||'{}');}catch{return toast('测试数据不是有效 JSON','error');}const button=$('#confirmRunFlow',node);button.disabled=true;try{const run=await api(`/api/flows/${flow.id}/run`,{method:'POST',body:JSON.stringify({headless:false,data})});node.remove();$('#flowRunResult').innerHTML=runResultHtml(run);toast('公共流程回放通过');}catch(error){node.remove();$('#flowRunResult').innerHTML=error.payload?.status?runResultHtml(error.payload):`<div class="run-summary failure">${esc(error.message)}</div>`;toast('公共流程回放失败','error');}finally{await refresh(true);}};}
async function deleteFlow(flow){if(!confirm(`删除公共流程“${flow.name}”？`))return;try{await api(`/api/flows/${flow.id}`,{method:'DELETE'});selectedFlowId=undefined;toast('公共流程已删除');await refresh();}catch(error){toast(error.message,'error');}}
function openPlanModal(plan){const node=modal(`<h2>${plan?'编辑':'新建'}测试计划</h2><p class="muted">计划名称会用作本地测试文件夹名。</p><div class="field-grid"><div class="field full"><label>计划名称</label><input id="mName" value="${esc(plan?.name||'')}"></div><div class="field full"><label>计划说明</label><textarea id="mDesc">${esc(plan?.description||'')}</textarea></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="mSave">保存</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#mSave',node).onclick=async()=>{try{const saved=await api(plan?`/api/plans/${plan.id}`:'/api/plans',{method:plan?'PUT':'POST',body:JSON.stringify({name:$('#mName',node).value.trim()||'新测试计划',description:$('#mDesc',node).value.trim()})});node.remove();selectedPlanId=saved.id;view='plans';toast('测试计划已保存');await refresh();}catch(error){toast(error.message,'error');}};}
function openCaseModal(planId){const node=modal(`<h2>新建测试用例</h2><p class="muted">选择适合你的编辑方式，之后仍可随时切换。</p><div class="field-grid"><div class="field full"><label>用例名称</label><input id="mCaseName" placeholder="例如：有效账号登录"></div><div class="field full"><label>编辑模式</label><select id="mMode"><option value="visual">无代码步骤（适合小白）</option><option value="code">Playwright 代码（适合开发者）</option></select></div><div class="field full"><label>加入计划</label><select id="mPlan"><option value="">暂不加入</option>${state.plans.map(p=>`<option value="${p.id}" ${p.id===planId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="mCreate">创建用例</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#mCreate',node).onclick=async()=>{try{const testCase=await api('/api/cases',{method:'POST',body:JSON.stringify({name:$('#mCaseName',node).value.trim()||'新测试用例',editorMode:$('#mMode',node).value})});const targetPlan=$('#mPlan',node).value;if(targetPlan)await api(`/api/plans/${targetPlan}/cases/${testCase.id}`,{method:'POST'});node.remove();selectedCaseId=testCase.id;view='cases';caseTab=$('#mMode',node).value==='code'?'code':'visual';toast('测试用例已创建');await refresh();}catch(error){toast(error.message,'error');}};}
function openAddCase(plan){const candidates=state.cases.filter(c=>!plan.caseIds.includes(c.id));const node=modal(`<h2>加入已有测试用例</h2><p class="muted">加入后会把 JS 和 Python 文件保存到该计划文件夹。</p><div class="list">${candidates.map(caseRowHtml).join('')||emptyHtml('没有可加入的用例','请先新建一个测试用例。')}</div><div class="actions" style="margin-top:16px"><button class="btn secondary" data-close>关闭</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$$('[data-case]',node).forEach(item=>item.onclick=async()=>{await api(`/api/plans/${plan.id}/cases/${item.dataset.case}`,{method:'POST'});node.remove();toast('用例已加入计划并保存源码文件');await refresh();});}
async function deletePlan(plan){if(!confirm(`删除测试计划“${plan.name}”？计划内测试用例不会删除。`))return;await api(`/api/plans/${plan.id}`,{method:'DELETE'});selectedPlanId=undefined;toast('测试计划已删除');await refresh();}
async function deleteCase(testCase){if(!confirm(`删除测试用例“${testCase.name}”？执行记录和 artifact 会保留。`))return;await api(`/api/cases/${testCase.id}`,{method:'DELETE'});selectedCaseId=undefined;view='cases';toast('测试用例已删除');await refresh();}

$$('.nav-link').forEach(node=>node.onclick=()=>go(node.dataset.view));
$('#newPlan').onclick=()=>openPlanModal(); $('#newCase').onclick=()=>openCaseModal();
window.addEventListener('i18n:change',()=>{ updateShell(); render(); window.I18N.translateTree(document); });
refresh().catch(error=>{toast(`加载失败：${error.message}`,'error');$('#content').innerHTML=emptyHtml('无法加载本地数据','请确认服务器正在运行，然后刷新页面。');});
